import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "../App.css";

function Home() {
  const navigate = useNavigate();

  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [template, setTemplate] = useState("simple");
  const [matchData, setMatchData] = useState(null);
  const [photo, setPhoto] = useState(null);

  // ================= AUTH =================
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) navigate("/login");
  }, [navigate]);

  const handleAuthError = (res) => {
    if (res.status === 401) {
      alert("Session expired. Login again.");
      localStorage.removeItem("token");
      navigate("/login");
      return true;
    }
    return false;
  };

  // ================= OPTIMIZE =================
  const handleOptimize = async () => {
    if (!resumeText.trim() || !jobDesc.trim()) {
      return alert("Provide Resume + JD");
    }

    setLoading(true);
    setMatchData(null);

    try {
      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
          template,
        }),
      });

      if (handleAuthError(res)) return;

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Optimization failed");
        return;
      }

      setResult(data);
    } catch (err) {
      console.error(err);
      alert("Server error");
    }

    setLoading(false);
  };

  // ================= MATCH =================
  const handleMatch = async () => {
    if (!resumeText.trim()) {
      return alert("Provide resume first");
    }

    try {
      const res = await fetch("http://localhost:5000/api/resume/match", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          resumeText,
          jobDesc,
        }),
      });

      if (handleAuthError(res)) return;

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Match failed");
        return;
      }

      setMatchData(data);
    } catch (err) {
      console.error(err);
      alert("Match error");
    }
  };

  // ================= SAVE =================
  const handleSave = async () => {
    if (!result) return alert("Optimize first");

    try {
      const res = await fetch("http://localhost:5000/api/resume/save", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          text: result.optimizedText,
          atsScore: result.score,
        }),
      });

      if (handleAuthError(res)) return;

      const data = await res.json();

      if (!res.ok) {
        alert(data.msg || "Save failed");
        return;
      }

      alert("Saved successfully");
      navigate("/dashboard");
    } catch (err) {
      console.error(err);
      alert("Save failed");
    }
  };

  // ================= DOWNLOAD (FIXED) =================
  const handleDownload = async () => {
    if (!result) return alert("Optimize first");

    try {
      const res = await fetch("http://localhost:5000/api/resume/download", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({
          text: result.optimizedText,
          template,
          photo, // 🔥 THIS IS THE FIX
        }),
      });

      if (handleAuthError(res)) return;

      const blob = await res.blob();
      const url = window.URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = "resume.pdf";
      a.click();
    } catch (err) {
      console.error(err);
      alert("Download failed");
    }
  };

  // ================= FILE UPLOAD =================
  const uploadPDF = async (file, setState) => {
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch(
        "http://localhost:5000/api/resume/upload-pdf",
        {
          method: "POST",
          headers: {
            Authorization: "Bearer " + localStorage.getItem("token"),
          },
          body: formData,
        }
      );

      if (handleAuthError(res)) return;

      const data = await res.json();

      if (!data.text) {
        alert("Parsing failed");
        return;
      }

      setState(data.text);
    } catch (err) {
      alert("Upload error");
    }
  };

  const handleResumeUpload = (e) => {
    if (e.target.files[0]) {
      uploadPDF(e.target.files[0], setResumeText);
    }
  };

  const handleJDUpload = (e) => {
    if (e.target.files[0]) {
      uploadPDF(e.target.files[0], setJobDesc);
    }
  };

  // ================= PHOTO =================
  const handlePhoto = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      setPhoto(reader.result.split(",")[1]); // base64 clean
    };
    reader.readAsDataURL(file);
  };

  // ================= UI =================
  return (
  <div className="dashboard">

    <div className="sidebar">
      <h2 className="logo">CareerForge</h2>

      <button onClick={() => navigate("/")}>Dashboard</button>
      <button onClick={() => navigate("/dashboard")}>Resume</button>
      <button onClick={() => navigate("/analytics")}>Analytics</button>
      <button onClick={() => navigate("/settings")}>Settings</button>
    </div>

    <div className="main">
        <h1>CareerForge Pro 🚀</h1>

        <div className="main-grid">
          <div className="card">
            <h3>Resume</h3>
            <input type="file" accept=".pdf" onChange={handleResumeUpload} />
            <textarea
              placeholder="Paste Resume..."
              value={resumeText}
              onChange={(e) => setResumeText(e.target.value)}
            />

            <h3>Job Description</h3>
            <input type="file" accept=".pdf" onChange={handleJDUpload} />
            <textarea
              placeholder="Paste Job Description..."
              value={jobDesc}
              onChange={(e) => setJobDesc(e.target.value)}
            />

            <h3>Upload Photo</h3>
            <input type="file" onChange={handlePhoto} />

            <select onChange={(e) => setTemplate(e.target.value)}>
              <option value="simple">Simple</option>
              <option value="modern">Modern</option>
              <option value="professional">Professional</option>
            </select>

            <button onClick={handleOptimize}>
              {loading ? "Optimizing..." : "Optimize Resume"}
            </button>

            <button onClick={handleMatch}>Check Job Match</button>
          </div>

          {result && (
            <div className="card">
              <h2>ATS Score: {result.score}</h2>
              <pre>{result.optimizedText}</pre>

              <button onClick={handleSave}>Save Resume</button>
              <button onClick={handleDownload}>Download PDF</button>

              {matchData && (
                <div>
                  <h3>Match Score: {matchData.matchScore}%</h3>

                  <h4>Matched Skills</h4>
                  <ul>
                    {matchData.matchedSkills.map((s, i) => (
                      <li key={i}>{s}</li>
                    ))}
                  </ul>

                  <h4>Missing Skills</h4>
                  <ul>
                    {matchData.missingSkills.map((s, i) => (
                      <li key={i}>{s}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Home;
